fun main() = kotlinx.coroutines.runBlocking {
    val table = kotlinx.coroutines.flow.MutableStateFlow(emptyList<Task>())
    val dao = object : TaskDao {
        override fun observeAll(): Flow<List<Task>> = table
        override suspend fun insert(task: Task) { table.value = table.value.filter { it.id != task.id } + task }
        override suspend fun delete(task: Task) { table.value = table.value - task }
    }
    dao.insert(Task(1, "хлеб"))
    dao.insert(Task(2, "сыр"))
    dao.delete(Task(1, "хлеб"))
    println(table.value)
}

